-- ---------------------------------------------------------------
-- eti:etica:1 · O que são ética e moral
-- ---------------------------------------------------------------
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:1', 0, 'mc', $q$A reflexão filosófica sobre os costumes e sobre o que é certo ou errado, que fundamenta as regras de convivência, é chamada de:$q$, $j${"opts":["Ética","Estética","Economia","Etiqueta"],"a":0}$j$, $q$Ética é a parte da filosofia que reflete sobre a moral e sobre as ações humanas.$q$, 1);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:1', 1, 'mc', $q$O conjunto de regras, hábitos e costumes que uma sociedade adota em determinada época, orientando o comportamento das pessoas, é a:$q$, $j${"opts":["Lógica","Moral","Genética","Gramática"],"a":1}$j$, $q$Moral vem do latim mores, costumes: são as regras de conduta de um grupo em um tempo e lugar.$q$, 2);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:1', 2, 'mc', $q$Qual situação é um exemplo de decisão ética?$q$, $j${"opts":["Devolver ao caixa o troco que veio a mais","Copiar a prova do colega sem ele ver","Furar a fila quando ninguém está olhando","Esconder um erro para não pedir desculpas"],"a":0}$j$, $q$Agir eticamente é fazer o certo mesmo quando ninguém está vendo — como devolver o troco errado.$q$, 1);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:1', 3, 'tf', $q$Julgue a afirmação sobre ética e moral$q$, $j${"stmt":"A moral pode mudar de uma época para outra e de uma cultura para outra; a ética é a reflexão crítica sobre essas regras.","a":true}$j$, $q$Verdadeiro: os costumes variam no tempo e no espaço; a ética pensa criticamente sobre eles.$q$, 2);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:1', 4, 'bank', $q$Complete a frase sobre ética e moral$q$, $j${"parts":["A "," é o conjunto de costumes e regras de uma sociedade; a "," é a reflexão filosófica sobre essas regras."],"a":["moral","ética"],"extra":["lei","arte"]}$j$, $q$Moral: as regras vividas. Ética: a reflexão sobre elas.$q$, 2);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:1', 5, 'match', $q$Associe cada conceito à sua definição$q$, $j${"pairs":[["Ética","Reflexão sobre o certo e o errado"],["Moral","Costumes e regras da sociedade"],["Lei","Norma escrita e obrigatória do Estado"],["Etiqueta","Regras de comportamento social, como à mesa"]]}$j$, $q$Ética reflete, moral orienta, lei obriga e etiqueta organiza a convivência social.$q$, 2);

-- eti:etica:2 · Valores e virtudes
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:2', 0, 'mc', $q$Agir de acordo com a verdade, mesmo quando isso traz prejuízo próprio, é demonstrar o valor da:$q$, $j${"opts":["Honestidade","Vaidade","Inveja","Indiferença"],"a":0}$j$, $q$Honestidade é falar e agir conforme a verdade, mesmo quando custa caro.$q$, 1);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:2', 1, 'mc', $q$A virtude de reconhecer os próprios erros e limites, sem se achar melhor que os outros, é a:$q$, $j${"opts":["Arrogância","Humildade","Covardia","Preguiça"],"a":1}$j$, $q$Humildade é reconhecer limites e erros; o contrário da arrogância.$q$, 1);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:2', 2, 'mc', $q$Para Aristóteles, a virtude é um hábito que se aprende com a prática e fica no meio-termo entre dois extremos. A coragem, por exemplo, fica entre:$q$, $j${"opts":["A covardia e a imprudência","A alegria e a tristeza","A riqueza e a pobreza","O amor e o ódio"],"a":0}$j$, $q$Para Aristóteles, a coragem é o meio-termo: nem fugir de tudo (covardia), nem se arriscar sem pensar (imprudência).$q$, 3);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:2', 3, 'tf', $q$Julgue a afirmação sobre os valores$q$, $j${"stmt":"Justiça, solidariedade, respeito e responsabilidade são exemplos de valores que orientam a boa convivência.","a":true}$j$, $q$Verdadeiro: valores são princípios que guiam nossas escolhas e a vida em comunidade.$q$, 1);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:2', 4, 'bank', $q$Complete a frase sobre as virtudes$q$, $j${"parts":["Quem cumpre o que promete demonstra ","; quem ajuda os outros sem esperar nada em troca demonstra ","."],"a":["responsabilidade","solidariedade"],"extra":["inveja","preguiça"]}$j$, $q$Responsabilidade é responder pelos compromissos; solidariedade é ajudar pensando no outro.$q$, 1);
select public.fj_seed_q('eti', 'eti:etica', 'eti:etica:2', 5, 'order', $q$Ordene os passos de uma decisão responsável diante de um dilema$q$, $j${"items":["Perceber o problema e quem será afetado","Pensar nas opções e em suas consequências","Escolher a opção mais justa","Assumir a responsabilidade pelo que foi feito"]}$j$, $q$Decidir bem é perceber, pesar as consequências, escolher com justiça e assumir o resultado.$q$, 2);

