-- eti:respeito:1 · Empatia e escuta
-- ---------------------------------------------------------------
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:1', 0, 'mc', $q$A capacidade de se colocar no lugar do outro e tentar entender o que ele sente é chamada de:$q$, $j${"opts":["Apatia","Empatia","Egoísmo","Timidez"],"a":1}$j$, $q$Empatia é sentir com o outro: imaginar-se no lugar dele para compreendê-lo.$q$, 1);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:1', 1, 'mc', $q$Qual atitude mostra escuta ativa numa conversa?$q$, $j${"opts":["Olhar para a pessoa e perguntar para entender melhor","Interromper para dar logo a sua opinião","Mexer no celular enquanto o outro fala","Mudar de assunto no meio da fala"],"a":0}$j$, $q$Escuta ativa é prestar atenção de verdade: olhar, não interromper e perguntar para compreender.$q$, 1);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:1', 2, 'mc', $q$Um colega novo chegou à turma e está sozinho no intervalo. A atitude empática é:$q$, $j${"opts":["Convidá-lo para participar do grupo","Fingir que não viu","Rir do jeito dele","Esperar que ele se vire sozinho"],"a":0}$j$, $q$Empatia na prática: perceber como o outro se sente e agir para acolher.$q$, 1);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:1', 3, 'tf', $q$Julgue a afirmação sobre a empatia$q$, $j${"stmt":"Ter empatia é concordar com tudo o que o outro diz.","a":false}$j$, $q$Falso: empatia é compreender o que o outro sente — dá para compreender e, ainda assim, discordar com respeito.$q$, 2);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:1', 4, 'bank', $q$Complete a frase sobre a convivência$q$, $j${"parts":["A "," é se colocar no lugar do outro; a escuta "," é ouvir com atenção, sem interromper, buscando compreender."],"a":["empatia","ativa"],"extra":["antipatia","distraída"]}$j$, $q$Empatia e escuta ativa são a base do diálogo e da boa convivência.$q$, 1);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:1', 5, 'match', $q$Associe a atitude à sua definição$q$, $j${"pairs":[["Empatia","Compreender o sentimento do outro"],["Diálogo","Conversa em que os dois lados falam e ouvem"],["Tolerância","Conviver em paz com quem pensa diferente"],["Cooperação","Trabalhar junto por um objetivo comum"]]}$j$, $q$Quatro atitudes que tornam a convivência possível: empatia, diálogo, tolerância e cooperação.$q$, 1);

-- eti:respeito:2 · Bullying e respeito às diferenças
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:2', 0, 'mc', $q$Agressões repetidas e intencionais contra a mesma pessoa, como apelidos ofensivos e exclusão, caracterizam:$q$, $j${"opts":["Brincadeira","Bullying","Debate","Competição"],"a":1}$j$, $q$Bullying é a intimidação sistemática: agressão repetida e de propósito contra alguém. Brincadeira todo mundo ri junto; no bullying, alguém sofre.$q$, 1);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:2', 1, 'mc', $q$Quando as agressões acontecem pela internet (grupos, redes sociais, jogos), falamos de:$q$, $j${"opts":["Cyberbullying","Netiqueta","Spam","Streaming"],"a":0}$j$, $q$Cyberbullying é o bullying no ambiente digital — e pode se espalhar ainda mais rápido.$q$, 1);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:2', 2, 'mc', $q$Quem presencia um colega sofrendo bullying deve:$q$, $j${"opts":["Não rir, apoiar a vítima e avisar um adulto de confiança","Filmar e postar nas redes","Fingir que não viu para não se envolver","Entrar na zoação para não sobrar"],"a":0}$j$, $q$Quem assiste e ri fortalece a agressão; apoiar a vítima e avisar um adulto ajuda a interromper.$q$, 1);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:2', 3, 'tf', $q$Julgue a afirmação sobre o combate ao bullying$q$, $j${"stmt":"No Brasil, uma lei de 2015 instituiu o programa de combate à intimidação sistemática (bullying), que as escolas devem aplicar.","a":true}$j$, $q$Verdadeiro: a Lei 13.185/2015 define o bullying como intimidação sistemática e obriga ações de prevenção.$q$, 3);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:2', 4, 'bank', $q$Complete a frase sobre as diferenças$q$, $j${"parts":["Respeitar as "," é reconhecer que as pessoas têm origens, crenças e jeitos variados; tratar alguém pior por causa disso é ","."],"a":["diferenças","discriminação"],"extra":["regras","educação"]}$j$, $q$A diversidade enriquece; a discriminação é tratar alguém pior por preconceito, e pode ser crime.$q$, 2);
select public.fj_seed_q('eti', 'eti:respeito', 'eti:respeito:2', 5, 'match', $q$Associe cada termo à sua definição$q$, $j${"pairs":[["Bullying","Agressão repetida e intencional"],["Cyberbullying","Agressão pela internet"],["Preconceito","Julgamento sem conhecer a pessoa"],["Discriminação","Tratar alguém pior por preconceito"]]}$j$, $q$Preconceito é a ideia; discriminação é a atitude; bullying e cyberbullying são agressões repetidas.$q$, 2);

