select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:1', 0, 'mc', $q$A lei mais importante do Brasil, que organiza o Estado e garante os direitos fundamentais, promulgada em 1988, é:$q$, $j${"opts":["A Constituição Federal, chamada de Constituição Cidadã","O Código de Trânsito","O Estatuto do Torcedor","A CLT"],"a":0}$j$, $q$A Constituição de 1988 está acima das outras leis: todas precisam respeitá-la.$q$, 1);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:1', 1, 'mc', $q$São direitos sociais garantidos pela Constituição:$q$, $j${"opts":["Educação, saúde e trabalho","Carro, celular e viagem","Fama, riqueza e sorte","Apenas o voto"],"a":0}$j$, $q$O artigo 6º lista os direitos sociais: educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança e outros.$q$, 1);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:1', 2, 'mc', $q$O artigo 5º da Constituição afirma que todos são iguais perante a lei. Isso significa que:$q$, $j${"opts":["A lei vale para todas as pessoas, sem privilégios","Só os ricos têm direitos","A lei vale só para adultos","Cada um escolhe as leis que quer seguir"],"a":0}$j$, $q$Igualdade perante a lei: ninguém está acima dela e ninguém pode ser tratado como inferior por ela.$q$, 2);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:1', 3, 'tf', $q$Julgue a afirmação sobre a Constituição$q$, $j${"stmt":"A Constituição de 1988 é chamada de Constituição Cidadã porque ampliou direitos e foi feita na redemocratização, após a ditadura militar.","a":true}$j$, $q$Verdadeiro: ela marcou a volta da democracia e ampliou direitos e garantias dos cidadãos.$q$, 2);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:1', 4, 'bank', $q$Complete a frase sobre as liberdades$q$, $j${"parts":["A Constituição garante a liberdade de "," (ninguém é obrigado a seguir uma religião) e a liberdade de "," do pensamento."],"a":["crença","expressão"],"extra":["imposto","trânsito"]}$j$, $q$Liberdade de crença e de expressão são direitos fundamentais do artigo 5º.$q$, 2);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:1', 5, 'match', $q$Associe o direito ao seu tipo$q$, $j${"pairs":[["Direito à vida","Direito individual"],["Educação","Direito social"],["Voto","Direito político"],["Meio ambiente equilibrado","Direito de todos (difuso)"]]}$j$, $q$Direitos individuais protegem cada pessoa; sociais garantem condições de vida; políticos permitem participar; difusos pertencem à coletividade.$q$, 3);

-- eti:direitos:2 · Deveres do cidadão e vida em comunidade
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:2', 0, 'mc', $q$Cidadania envolve direitos e também deveres. É um dever do cidadão:$q$, $j${"opts":["Respeitar as leis e os direitos dos outros","Ter casa na praia","Concordar sempre com o governo","Nunca reclamar de nada"],"a":0}$j$, $q$Cidadania é a via de mão dupla: exigir direitos e cumprir deveres, começando por respeitar a lei e o próximo.$q$, 1);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:2', 1, 'mc', $q$Jogar lixo no chão da praça prejudica:$q$, $j${"opts":["Toda a comunidade, porque o espaço é público","Ninguém","Só o prefeito","Só quem jogou"],"a":0}$j$, $q$Espaço público é de todos: sujá-lo transfere o custo e o incômodo para a comunidade inteira.$q$, 1);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:2', 2, 'mc', $q$Qual é um exemplo de cuidado com o patrimônio público?$q$, $j${"opts":["Conservar a escola e os livros didáticos","Pichar o muro da escola","Quebrar o banco da praça","Rasgar os livros da biblioteca"],"a":0}$j$, $q$Escola, livros, praças e hospitais públicos são pagos por todos — conservá-los é dever de cada um.$q$, 1);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:2', 3, 'tf', $q$Julgue a afirmação sobre os deveres$q$, $j${"stmt":"Pagar impostos e votar são deveres que sustentam os serviços públicos e a democracia.","a":true}$j$, $q$Verdadeiro: os impostos financiam os serviços públicos e o voto escolhe quem vai administrá-los.$q$, 1);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:2', 4, 'bank', $q$Complete a frase sobre o que é de todos$q$, $j${"parts":["O que é de uso de todos, como praças, escolas e hospitais públicos, chama-se patrimônio ","; cuidar dele é dever de "," cidadão."],"a":["público","todo"],"extra":["privado","nenhum"]}$j$, $q$Patrimônio público pertence à coletividade; danificá-lo prejudica (e custa para) todo mundo.$q$, 1);
select public.fj_seed_q('eti', 'eti:direitos', 'eti:direitos:2', 5, 'order', $q$Ordene os passos para resolver um problema do bairro, como a falta de iluminação numa rua$q$, $j${"items":["Identificar o problema e conversar com os vizinhos","Registrar o pedido na prefeitura ou na ouvidoria","Acompanhar a resposta do órgão público","Cobrar e divulgar a solução para a comunidade"]}$j$, $q$Participar é isso: identificar, acionar o órgão responsável, acompanhar e cobrar.$q$, 2);

